def solve_small():
    def can_reach_one(m, n, max_nums=200):
        x0 = Fraction(m, n)
        y0 = Fraction(n, m)
        nums = {x0, y0}

        for _ in range(100): # Max steps
            new_nums = set()
            nums_list = list(nums)
            for i in range(len(nums_list)):
                for j in range(i, len(nums_list)):
                    x = nums_list[i]
                    y = nums_list[j]

                    a = (x + y) / 2
                    if a == 1: return True
                    new_nums.add(a)

                    if x + y != 0:
                        h = (2 * x * y) / (x + y)
                        if h == 1: return True
                        new_nums.add(h)

            if new_nums.issubset(nums):
                break
            nums.update(new_nums)
            if len(nums) > max_nums:
                break
        return False

    results = []
    for m in range(1, 50):
        for n in range(1, m + 1):
            import math
            if math.gcd(m, n) == 1:
                if can_reach_one(m, n):
                    results.append((m, n))
    return results

